window.DEX_DATA["sources:backport-df9730f219176ebd"]={"json":{"skins":[{"filename":"mechanic.png"}],"names":[{"name":"修车师乔"},{"name":"扳手麦克"},{"name":"司机鲍勃"},{"name":"安格斯"},{"name":"维修师皮特"}],"chat":[{"lines":[{"text":"车轮吱吱响了吗？"},{"text":"把车开到我的修理厂，好好检修一下吧。"}]},{"lines":[{"text":"何必到处追宝可梦？这里有好车等着修呢。"},{"text":"在坏车的引擎盖下忙上一天，最有成就感了！"}]},{"lines":[{"text":"我需要放个假，整天钻车底可真累。"},{"text":"你能替我照看一会儿修理厂吗？我想歇歇。"}]},{"lines":[{"text":"我最喜欢早晨闻到润滑油的味道。"},{"text":"下次把车带来吧，我保证让它运转顺畅！"}]}]}};
